        pLevelUnknown->aCoordsAndSize[nCurrentNode].WorldPosition.x = pPrevCoordsEntry->WorldPosition.x;
      nPrevWorldSizeY = pPrevCoordsEntry->WorldSize.y;
      nPrevWorldPosY = pPrevCoordsEntry->WorldPosition.y;
