      pLevelUnknown->aCoordsAndSize[nCurrentNode].WorldPosition.y = pPrevCoordsEntry->WorldPosition.y - 0x10;
      return 1;
      case 2:
        pLevelUnknown->aCoordsAndSize[nCurrentNode].WorldPosition.x = pPrevCoordsEntry->WorldSize.x - pLevelUnknown->aCoordsAndSize[nCurrentNode].WorldSize.x + pPrevCoordsEntry->WorldPosition.x;
      nPrevWorldSizeY = pPrevCoordsEntry->WorldPosition.y;
      nPrevWorldPosY = pLevelUnknown->aCoordsAndSize[nCurrentNode].WorldSize.y;
      pLevelUnknown->aCoordsAndSize[nCurrentNode].WorldPosition.x += 0x10;
      pLevelUnknown->aCoordsAndSize[nCurrentNode].WorldPosition.y = nPrevWorldSizeY - nPrevWorldPosY;
      return 1;
      case 3:
