      pLevelUnknown->aCoordsAndSize[nCurrentNode].WorldPosition.y = pPrevCoordsEntry->WorldSize.y - pLevelUnknown->aCoordsAndSize[nCurrentNode].WorldSize.y + 0x10 + pPrevCoordsEntry->WorldPosition.y;
